"""Sites and products: the generic layout every construction project follows.

    projects/<site>/project.yaml                  site metadata (name, address, building type, ...)
    projects/<site>/specs/*.yaml                  spec-driven models (detail | house | room | element)
    projects/<site>/products/<name>/product.yaml  bespoke pipelines (film, viewer, report) and their steps
    projects/<site>/deliverables/<name>/          what gets handed over

No bpy here, so discovery works on machines and CI jobs without Blender.
"""
from dataclasses import dataclass, field
from pathlib import Path

import yaml

from bmodels.paths import BUILD, PROJECTS, ROOT

LEGACY_SPECS = ROOT / "specs"  # pre-site layout; still built until every spec lives under a site


@dataclass
class Product:
    site: "Site"
    name: str
    dir: Path
    meta: dict = field(default_factory=dict)

    @property
    def ref(self):
        return f"{self.site.name}/{self.name}"

    @property
    def deliverables(self):
        return self.site.dir / "deliverables" / self.name

    @property
    def build(self):
        return BUILD / self.site.name / self.name


@dataclass
class Site:
    name: str
    dir: Path
    meta: dict = field(default_factory=dict)

    @property
    def specs(self):
        return sorted((self.dir / "specs").glob("*.yaml"))

    @property
    def products(self):
        found = sorted(p.parent for p in (self.dir / "products").glob("*/product.yaml"))
        return [Product(self, d.name, d, _yaml(d / "product.yaml")) for d in found]

    @property
    def build(self):
        return BUILD / self.name


def _yaml(path):
    return yaml.safe_load(Path(path).read_text()) or {}


def sites():
    return [Site(p.parent.name, p.parent, _yaml(p)) for p in sorted(PROJECTS.glob("*/project.yaml"))]


def site(name):
    for s in sites():
        if s.name == name:
            return s
    raise SystemExit(f"No site '{name}' (projects/{name}/project.yaml). Sites: {', '.join(s.name for s in sites()) or 'none'}")


def product(ref):
    site_name, _, name = ref.partition("/")
    for p in site(site_name).products:
        if p.name == name:
            return p
    raise SystemExit(f"No product '{ref}'. Products: {', '.join(p.ref for p in site(site_name).products) or 'none'}")


def legacy_specs():
    return sorted(LEGACY_SPECS.glob("*.yaml"))


def all_specs():
    return [sp for s in sites() for sp in s.specs] + legacy_specs()


def site_of(spec_path):
    """The site a spec belongs to, or None for a legacy specs/ file."""
    spec_path = Path(spec_path).resolve()
    for s in sites():
        if spec_path.is_relative_to(s.dir.resolve()):
            return s
    return None


def build_dir(spec_path):
    """Where a spec's outputs go: build/<site>/<spec>/ (legacy specs keep build/<spec>/)."""
    s = site_of(spec_path)
    return (s.build if s else BUILD)


def resolve_specs(targets):
    """Spec files from paths, 'site', or 'site/spec-stem' targets. No targets = every spec."""
    if not targets:
        return all_specs()
    out = []
    for t in targets:
        p = Path(t)
        if p.suffix in (".yaml", ".yml") and p.exists():
            out.append(p)
            continue
        site_name, _, stem = t.partition("/")
        specs = site(site_name).specs
        picked = [sp for sp in specs if not stem or sp.stem == stem]
        if not picked:
            raise SystemExit(f"No spec '{stem}' in {site_name}. Specs: {', '.join(sp.stem for sp in specs) or 'none'}")
        out += picked
    return out

"""Large files live in GitHub Releases, described by a checksum manifest committed next to the work.

Manifest (JSON), paths relative to the manifest's directory unless noted:

    {
      "repository": "owner/repo",
      "tag": "highland-repipe-2026-10-17",
      "asset_directory": "../../deliverables/x/assets",   # optional local copy checked before downloading
      "assets": [
        {"name": "film-4K.mp4", "bytes": 123, "sha256": "...",
         "dest": "renders/film-4K.mp4",                    # optional: copy here after verifying
         "extract": {"zip/member.blend": "local/path.blend"}}  # optional: zip members to restore
      ]
    }

pull   download missing/mismatched assets into build/assets/<tag>/ (never over committed or LFS files),
       verify every checksum, then copy `dest` files and extract `extract` members. Restores are
       all-or-nothing: every archive and existing target is checked before anything is written, and a
       locally modified target is preserved (error), never overwritten.
verify check the local copies (asset_directory or the download cache) against the manifest.
push   upload files to the release (created if missing) and record their bytes and sha256.
"""
import hashlib
import json
import shutil
import subprocess
import zipfile
from pathlib import Path

from bmodels.paths import BUILD


def digest(path):
    h = hashlib.sha256()
    with Path(path).open("rb") as f:
        for chunk in iter(lambda: f.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()


def matches(path, record):
    path = Path(path)
    return path.is_file() and path.stat().st_size == record["bytes"] and digest(path) == record["sha256"]


class Manifest:
    def __init__(self, path):
        self.path = Path(path).resolve()
        self.dir = self.path.parent
        self.data = json.loads(self.path.read_text())
        self.tag = self.data["tag"]
        self.repo = self.data.get("repository")
        self.cache = BUILD / "assets" / self.tag

    @property
    def assets(self):
        return self.data.setdefault("assets", [])

    def local(self, record):
        """First verified local copy of an asset, or None."""
        candidates = [self.cache / record["name"]]
        if self.data.get("asset_directory"):
            candidates.insert(0, self.dir / self.data["asset_directory"] / record["name"])
        return next((c for c in candidates if matches(c, record)), None)

    def save(self):
        self.path.write_text(json.dumps(self.data, indent=2) + "\n")


def _gh(*args):
    subprocess.run(["gh", *args], check=True)


def verify(manifest):
    m = Manifest(manifest)
    missing = [a["name"] for a in m.assets if not m.local(a)]
    for a in m.assets:
        print(f"{'ok     ' if a['name'] not in missing else 'MISSING'} {a['name']}")
    return not missing


def pull(manifest, names=None):
    m = Manifest(manifest)
    wanted = [a for a in m.assets if not names or a["name"] in names]
    m.cache.mkdir(parents=True, exist_ok=True)
    for a in wanted:
        if m.local(a):
            continue
        repo = ["-R", m.repo] if m.repo else []
        _gh("release", "download", m.tag, *repo, "-p", a["name"], "-D", str(m.cache), "--clobber")
        if not matches(m.cache / a["name"], a):
            raise ValueError(f"Release checksum mismatch: {a['name']}")
    sources = {a["name"]: m.local(a) for a in wanted}

    # Check every target before writing any (all-or-nothing; preserve local edits).
    plan = []
    for a in wanted:
        src = sources[a["name"]]
        if a.get("dest"):
            plan.append((m.dir / a["dest"], a["sha256"], lambda out, src=src: shutil.copyfile(src, out)))
        for member, rel in (a.get("extract") or {}).items():
            with zipfile.ZipFile(src) as z, z.open(member) as f:
                want = hashlib.file_digest(f, "sha256").hexdigest()
            def write(out, src=src, member=member):
                with zipfile.ZipFile(src) as z, z.open(member) as f, out.open("xb") as o:
                    shutil.copyfileobj(f, o)
            plan.append((m.dir / rel, want, write))
    for target, want, _ in plan:
        if target.exists() and digest(target) != want:
            raise FileExistsError(f"Preserving a modified local asset: {target}")

    restored = 0
    for target, _, write in plan:
        if target.exists():
            continue
        target.parent.mkdir(parents=True, exist_ok=True)
        tmp = target.with_name(target.name + ".part")
        try:
            write(tmp)
            tmp.replace(target)
        finally:
            tmp.unlink(missing_ok=True)
        restored += 1
    print(f"{len(wanted)} release assets verified; restored {restored} files. Existing matching files preserved.")


def push(manifest, files, title=None):
    m = Manifest(manifest)
    repo = ["-R", m.repo] if m.repo else []
    if subprocess.run(["gh", "release", "view", m.tag, *repo], capture_output=True).returncode:
        _gh("release", "create", m.tag, *repo, "--title", title or m.tag, "--notes", "")
    _gh("release", "upload", m.tag, *repo, "--clobber", *map(str, files))
    for f in map(Path, files):
        rec = next((a for a in m.assets if a["name"] == f.name), None)
        if rec is None:
            rec = {"name": f.name}
            m.assets.append(rec)
        rec.update(bytes=f.stat().st_size, sha256=digest(f))
    m.save()
    print(f"Uploaded {len(files)} files to {m.tag}; manifest updated: {m.path}")

